// Recapture the "Choose what to keep" step with Question and Claim fully visible; never clicks Import.
import { writeFileSync } from "fs";
const DEMO = "/Users/Shared/dg-schema-lab-notebook.json";
const OUT = "/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/0f317e52-46cd-4e60-bde3-483f6eb34e20/scratchpad/shots/import-05-conflicts-chosen-v2.png";
const MODAL = ".modal-container .modal";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
export default {
  name: "Conflict step: Question and Claim visible",
  input: "import Lab notebook file; Choose what to keep; Use all from Lab notebook on Question and Question template; no import",
  expected: "Question and Claim tables fully visible, template note shown",
  setup: async ({ client, json }) => {
    await client.evaluate(`document.querySelectorAll(".notice").forEach((n) => n.remove());
      const leaf = app.workspace.getLeaf("tab"); app.workspace.setActiveLeaf(leaf, { focus: true });
      if (!window.__dgOrigRequire) window.__dgOrigRequire = window.require;
      const orig = window.__dgOrigRequire;
      const dialog = { showOpenDialog: async () => ({ canceled: false, filePaths: [${json(DEMO)}] }), showSaveDialog: async () => ({ canceled: true }) };
      window.require = (n) => (n === "electron" ? { dialog } : orig(n)); return true;`);
  },
  run: async ({ client, json, vault }) => {
    const click = (text, starts) => client.evaluate(`const b = Array.from(document.querySelectorAll(${json(`${MODAL} button`)}))
      .find((el) => ${starts ? `el.textContent.trim().startsWith(${json(text)})` : `el.textContent.trim() === ${json(text)}`}); if (!b) return false; b.click(); return true;`);
    await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:import-dg-schema`)});`);
    await client.waitFor(`return !!document.querySelector(${json(MODAL)})?.textContent.includes("Choose schema file");`, { label: "pick" });
    await click("Choose schema file");
    await client.waitFor(`return !!document.querySelector(${json(MODAL)})?.textContent.includes("Import schema preview");`, { label: "preview" });
    await click("Choose what to keep", true);
    await client.waitFor(`return !!document.querySelector(${json(MODAL)})?.textContent.includes("Every field starts on your value");`, { label: "conflicts" });
    const layout = await client.evaluate(`const secs = Array.from(document.querySelectorAll(${json(`${MODAL} section`)})).filter((s) => s.querySelector("h5"));
      const by = (n) => secs.find((s) => s.querySelector("h5").textContent.trim() === n);
      by("Question").querySelector("thead th:last-child button").click();
      by("Question template.md")?.querySelector("thead th:last-child button").click();
      const panel = document.querySelector(${json(`${MODAL} .max-h-96`)}); panel.scrollTop = 0;
      return { claimBottom: by("Claim").getBoundingClientRect().bottom, panelTop: panel.getBoundingClientRect().top, viewport: innerHeight };`);
    // End the list right after Claim's table so no item is cut mid-way.
    await client.evaluate(`const panel = document.querySelector(${json(`${MODAL} .max-h-96`)});
      panel.style.maxHeight = ${Math.ceil(layout.claimBottom - layout.panelTop) + 2} + "px"; return true;`);
    await sleep(400);
    const r = await client.evaluate(`const b = document.querySelector(${json(MODAL)}).getBoundingClientRect(); return { x: b.x, y: b.y, width: b.width, height: b.height };`);
    const pad = 2;
    const { data } = await client.send("Page.captureScreenshot", { format: "png", clip: { x: r.x - pad, y: r.y - pad, width: r.width + pad * 2, height: r.height + pad * 2, scale: 1 } });
    writeFileSync(OUT, Buffer.from(data, "base64"));
    return { ...layout, modal: r };
  },
  expect: (a) => ({ pass: a.modal.y >= 0 && a.modal.y + a.modal.height <= a.viewport, actual: JSON.stringify(a) }),
  teardown: async ({ client }) => {
    await client.evaluate(`if (window.__dgOrigRequire) { window.require = window.__dgOrigRequire; delete window.__dgOrigRequire; } return true;`);
  },
};
EOF
